<template><ElConfigProvider :locale="zh" size="large"><ElContainer class="v1-shell"><ElMain class="v1-content v1-full"><ElSpace direction="vertical" fill class="v1-page" :size="20">
 <ElPageHeader title="天枢" content="模拟平台"><template #icon><ArtLogo :size="44" /></template><template #extra><ElSpace><ElTag type="warning">全部为模拟数据</ElTag><ElButton circle aria-label="切换主题" @click="theme.switchThemeStyles(setting.isDark?'light':'dark')"><ArtSvgIcon icon="ri:contrast-2-line" /></ElButton><ElButton @click="load">刷新</ElButton></ElSpace></template></ElPageHeader>
 <ElAlert v-if="error" :title="error" type="error" show-icon :closable="false" />
 <ElRow :gutter="20"><ElCol :span="8"><ElCard shadow="never"><ElStatistic title="模拟设备" :value="state.meters.length" /></ElCard></ElCol><ElCol :span="8"><ElCard shadow="never"><ElStatistic title="合计模拟功率" :value="state.meters.reduce((s,m)=>s+m.power_w,0)/1000" :precision="2" suffix="kW" /></ElCard></ElCol><ElCol :span="8"><ElCard shadow="never"><ElStatistic title="已启用网关" :value="state.gateways.filter(g=>g.enabled).length" /></ElCard></ElCol></ElRow>
 <ElCard shadow="never"><ElTabs v-model="tab">
  <ElTabPane name="meters" label="电表 API"><ElSpace class="v1-spread"><ElSpace><ElButton type="primary" @click="editMeter()">添加模拟设备</ElButton><ElButton @click="showKey">查看 API 接入令牌</ElButton></ElSpace><ElTag :type="Date.now()/1000-state.heartbeat<5?'success':'danger'">模拟引擎</ElTag></ElSpace>
   <ArtTable :data="state.meters" height="440" :show-table-header="false" class="v1-gap"><ElTableColumn prop="name" label="模拟设备" min-width="170" /><ElTableColumn label="API 能力" width="120"><template #default="{row}">{{modes[row.mode]}}</template></ElTableColumn><ElTableColumn label="余额 / kWh" min-width="130"><template #default="{row}">{{row.balance_kwh.toFixed(4)}}</template></ElTableColumn><ElTableColumn label="累计 / kWh" min-width="130"><template #default="{row}">{{row.cumulative_kwh.toFixed(4)}}</template></ElTableColumn><ElTableColumn label="功率 / W" width="120"><template #default="{row}">{{row.power_w.toFixed(1)}}</template></ElTableColumn><ElTableColumn label="通信 / 故障" min-width="180"><template #default="{row}"><ElSpace><ElTag :type="row.online?'success':'info'">{{row.online?'在线':'离线'}}</ElTag><ElTag :type="row.fault==='normal'?'info':'warning'">{{faults[row.fault]}}</ElTag></ElSpace></template></ElTableColumn><ElTableColumn label="操作" width="260" fixed="right"><template #default="{row}"><ElButton text @click="editMeter(row)">编辑</ElButton><ElButton text @click="connecting=row;connectionOpen=true">接入</ElButton><ElDropdown @command="kind=>meterAction(row,kind)"><ElButton text>操作<ArtSvgIcon icon="ri:arrow-down-s-line" /></ElButton><template #dropdown><ElDropdownMenu><ElDropdownItem command="recharge">模拟充值</ElDropdownItem><ElDropdownItem command="balance">设置余额 / 欠费</ElDropdownItem><ElDropdownItem v-if="row.controllable" command="relay">{{row.relay_on?'模拟现场断开':'模拟现场接通'}}</ElDropdownItem><ElDropdownItem command="reset" divided>累计读数清零</ElDropdownItem></ElDropdownMenu></template></ElDropdown></template></ElTableColumn></ArtTable>
  </ElTabPane>
  <ElTabPane name="gateways" label="设备网关"><ElButton type="primary" @click="editGateway()">添加模拟网关</ElButton><ArtTable :data="state.gateways" height="440" :show-table-header="false" class="v1-gap"><ElTableColumn prop="name" label="模拟网关" min-width="160" /><ElTableColumn prop="target" label="本机天枢地址" min-width="220" /><ElTableColumn label="状态" width="150"><template #default="{row}"><ElTag :type="!row.enabled?'info':row.status.state==='online'?'success':'danger'">{{!row.enabled?'已停用':row.status.state==='online'?'协议连接正常':'连接待检查'}}</ElTag></template></ElTableColumn><ElTableColumn label="回执" width="160"><template #default="{row}">{{ackModes[row.ack_mode]}}</template></ElTableColumn><ElTableColumn prop="status.message" label="最近结果" min-width="260" /><ElTableColumn label="操作" width="100" fixed="right"><template #default="{row}"><ElButton text @click="editGateway(row)">编辑</ElButton></template></ElTableColumn></ArtTable></ElTabPane>
  <ElTabPane name="camera" label="模拟监控" lazy><SimulatorMonitor v-if="tab==='camera'" :camera="state.camera" :request="api" @refresh="load" /></ElTabPane>
  <ElTabPane name="commands" label="控制回执"><ArtTable :data="state.commands" height="440" :show-table-header="false"><ElTableColumn prop="id" label="指令 ID" min-width="250" /><ElTableColumn label="模拟设备" min-width="160"><template #default="{row}">{{state.meters.find(m=>m.id===row.meter_id)?.name||'未映射设备'}}</template></ElTableColumn><ElTableColumn label="目标" width="100"><template #default="{row}">{{row.desired?'接通':'断开'}}</template></ElTableColumn><ElTableColumn label="状态" width="150"><template #default="{row}"><ElTag>{{commandStates[row.state]||row.state}}</ElTag></template></ElTableColumn><ElTableColumn prop="error" label="结果" min-width="240" /></ArtTable></ElTabPane>
  <ElTabPane name="events" label="运行日志"><ArtTable :data="state.events" height="440" :show-table-header="false"><ElTableColumn label="时间" width="190"><template #default="{row}">{{date(row.ts)}}</template></ElTableColumn><ElTableColumn prop="kind" label="类型" width="120" /><ElTableColumn prop="message" label="模拟事件" /></ArtTable></ElTabPane>
 </ElTabs></ElCard>
 </ElSpace></ElMain></ElContainer>
 <ElDrawer v-model="meterOpen" title="模拟设备参数" direction="rtl" size="min(620px,100vw)" destroy-on-close :close-on-click-modal="false"><ArtForm :key="draft.id||'new'" v-model="draft" :items="meterFields" :span="24" label-position="top" :show-submit="false" :show-reset="false" /><ElAlert v-if="formError" :title="formError" type="error" :closable="false" /><template #footer><ElButton @click="meterOpen=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="saveMeter">保存</ElButton></template></ElDrawer>
 <ElDrawer v-model="gatewayOpen" title="模拟网关配置" direction="rtl" size="min(720px,100vw)" destroy-on-close :close-on-click-modal="false"><ArtForm v-model="gatewayDraft" :items="gatewayFields" :span="24" label-position="top" :show-submit="false" :show-reset="false" /><ElDivider content-position="left">设备映射</ElDivider><ElEmpty v-if="!gatewayDraft.mappings.length" description="尚未添加设备映射" :image-size="72" /><ElCard v-for="(mapping,index) in gatewayDraft.mappings" :key="index" shadow="never" class="v1-mapping-card"><template #header><ElSpace class="v1-spread"><ElText tag="strong">映射 {{String(index+1).padStart(2,'0')}}</ElText><ElButton type="danger" link @click="gatewayDraft.mappings.splice(index,1)">移除</ElButton></ElSpace></template><ElForm label-position="top"><ElFormItem label="模拟设备"><ElSelect v-model="mapping.meter_id" aria-label="模拟设备" class="v1-full"><ElOption v-for="m in state.meters" :key="m.id" :label="m.name" :value="m.id" /></ElSelect></ElFormItem><ElFormItem label="天枢设备 ID"><ElInput v-model="mapping.device_id" placeholder="从天枢设备卡片复制" aria-label="天枢设备 ID" clearable /></ElFormItem></ElForm></ElCard><ElButton class="v1-gap v1-full" plain type="primary" @click="gatewayDraft.mappings.push({meter_id:'',device_id:''})"><ArtSvgIcon icon="ri:add-line" />添加设备映射</ElButton><ElAlert v-if="formError" :title="formError" type="error" class="v1-gap" :closable="false" /><template #footer><ElButton @click="gatewayOpen=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="saveGateway">保存网关</ElButton></template></ElDrawer>
 <ElDrawer v-model="connectionOpen" title="模拟电表 API 接入" direction="rtl" size="min(680px,100vw)" destroy-on-close><ElDescriptions :column="1" border><ElDescriptionsItem label="协议">通用 JSON · GET / POST</ElDescriptionsItem><ElDescriptionsItem label="认证">Authorization: Bearer &lt;模拟平台令牌&gt;</ElDescriptionsItem><ElDescriptionsItem label="业务成功">code = 0</ElDescriptionsItem></ElDescriptions><ElForm label-position="top" class="v1-gap"><ElFormItem label="接口地址"><ElInput :model-value="connectionURL" readonly /></ElFormItem><ElFormItem label="字段映射"><ElInput :model-value="connectionMapping" type="textarea" :rows="7" readonly /></ElFormItem></ElForm><ElButton @click="copyConnection">复制接口与映射</ElButton><ElDivider>天枢设备命名</ElDivider><ElTag type="warning">【模拟】{{connecting?.name}}</ElTag></ElDrawer>
 <ElDialog v-model="keyOpen" title="模拟 API 接入令牌" width="min(680px,94vw)" destroy-on-close align-center @closed="apiKey=''"><ElSpace direction="vertical" fill :size="18" class="v1-dialog-stack"><ElAlert title="令牌用于模拟接口认证，请勿填写到第三方系统" type="warning" show-icon :closable="false" /><ElInput class="v1-copy-field" :model-value="apiKey" type="password" show-password readonly aria-label="模拟 API 令牌"><template #append><ElButton @click="copy(apiKey)">复制</ElButton></template></ElInput></ElSpace><template #footer><ElButton type="primary" @click="keyOpen=false">完成</ElButton></template></ElDialog>
 <ElDialog v-model="actionOpen" :title="actionKind==='recharge'?'模拟充值':'设置模拟余额 / 欠费'" width="min(500px,94vw)" align-center><ElForm label-position="top"><ElFormItem label="电量 / kWh"><ElInputNumber v-model="amount" class="v1-full" :min="actionKind==='recharge'?0.001:-10000000" :max="10000000" :precision="3" /></ElFormItem></ElForm><template #footer><ElButton @click="actionOpen=false">取消</ElButton><ElButton type="primary" :loading="saving" @click="saveAction">确认模拟操作</ElButton></template></ElDialog>
 </ElConfigProvider></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';import SimulatorMonitor from './SimulatorMonitor.vue';import {ElMessage,ElMessageBox} from 'element-plus';import zh from 'element-plus/es/locale/lang/zh-cn';import {useSettingStore} from './art/store/modules/setting';import {initializeTheme,useTheme} from './art/hooks/core/useTheme';import {date} from './api';
const setting=useSettingStore(),theme=useTheme();initializeTheme();const state=ref({meters:[],gateways:[],commands:[],events:[],heartbeat:0}),tab=ref('meters'),error=ref(''),formError=ref(''),saving=ref(false),meterOpen=ref(false),gatewayOpen=ref(false),connectionOpen=ref(false),keyOpen=ref(false),apiKey=ref(''),draft=ref({}),gatewayDraft=ref({mappings:[]}),connecting=ref(null),actionOpen=ref(false),actionKind=ref(''),actionMeter=ref(null),amount=ref(10);let csrf='',timer,loading=false;
const modes={balance:'仅余额',cumulative:'累计电量',full:'完整计量'},faults={normal:'正常',http500:'HTTP 500',business:'业务失败',malformed:'格式错误',timeout:'延迟 12 秒',frozen:'读数冻结'},ackModes={success:'模拟成功',failure:'模拟拒绝',timeout:'不执行 / 无回执',mismatch:'回读不一致'},commandStates={received:'等待执行',executed:'待回执',failed:'拒绝待回执',acknowledged:'回执已送达',expired:'已过期',unknown:'结果未知',noack:'模拟无回执'};
const f=(key,label,type='input',props={})=>({key,label,type,props}),options=values=>Object.entries(values).map(([value,label])=>({value,label}));
const meterFields=computed(()=>[f('name','模拟设备名称'),f('mode','API 输出能力','select',{options:options(modes)}),f('nominal_w','模拟负载 / W','number',{min:0,max:10000000}),f('profile','功率变化','select',{options:options({constant:'恒定负载',wave:'周期波动',spike:'周期超限'})}),f('voltage','模拟电压 / V','number',{min:1,max:1000}),f('controllable','具备模拟开关','switch'),f('online','模拟通信在线','switch'),f('fault','API 故障','select',{options:options(faults)}),...(!draft.value.id?[f('balance_kwh','初始余额 / kWh','number',{min:-10000000,max:10000000}),f('cumulative_kwh','初始累计 / kWh','number',{min:0,max:10000000000})]:[])]);
const gatewayFields=[f('name','模拟网关名称'),f('target','本机天枢地址','input',{placeholder:'http://127.0.0.1:8791'}),f('token','专用测试网关令牌','input',{type:'password',showPassword:true,placeholder:'留空保留当前令牌'}),f('ack_mode','控制回执方式','select',{options:options(ackModes)}),f('ack_delay','模拟执行延迟 / 秒','number',{min:0,max:25}),f('simulation_only','确认是专用于模拟的测试网关','switch'),f('enabled','启用网关连接','switch')];
const connectionURL=computed(()=>connecting.value?location.origin+'/mock/meters/'+connecting.value.id:'');const connectionMapping=computed(()=>{const mode=connecting.value?.mode;return JSON.stringify({...(mode!=='cumulative'?{balance_kwh:'data.balance_kwh'}:{}),...(mode!=='balance'?{cumulative_kwh:'data.cumulative_kwh'}:{}),...(mode==='full'?{power_w:'data.power_w',voltage:'data.voltage'}:{})},null,2)});
async function api(path,body){const r=await fetch('/sim/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},...(body===undefined?{}:{body:JSON.stringify(body)})});const result=await r.json();if(!r.ok)throw Error(result.error||'模拟请求失败');return result}
async function load(){if(loading)return;loading=true;try{state.value=await api('state');error.value=''}catch(e){error.value=e.message}finally{loading=false}}
function editMeter(m){draft.value=m?JSON.parse(JSON.stringify(m)):{name:'模拟电表 '+String(state.value.meters.length+1).padStart(2,'0'),mode:'full',nominal_w:1000,profile:'wave',voltage:220,controllable:false,online:true,fault:'normal',balance_kwh:50,cumulative_kwh:0};formError.value='';meterOpen.value=true}
async function saveMeter(){saving.value=true;formError.value='';try{await api('meters',draft.value);meterOpen.value=false;await load();ElMessage.success('模拟设备已保存')}catch(e){formError.value=e.message}finally{saving.value=false}}
function editGateway(g){gatewayDraft.value=g?{...JSON.parse(JSON.stringify(g)),token:''}:{name:'模拟网关',target:'http://127.0.0.1:8791',token:'',ack_mode:'success',ack_delay:1,simulation_only:false,enabled:false,mappings:[]};formError.value='';gatewayOpen.value=true}
async function saveGateway(){saving.value=true;formError.value='';try{await api('gateways',gatewayDraft.value);gatewayDraft.value.token='';gatewayOpen.value=false;await load();ElMessage.success('模拟网关已保存')}catch(e){formError.value=e.message}finally{saving.value=false}}
async function showKey(){try{apiKey.value=(await api('credentials',{})).api_key;keyOpen.value=true}catch(e){ElMessage.error(e.message)}}
async function copyConnection(){try{await navigator.clipboard.writeText(connectionURL.value+'\ncode = 0\n'+connectionMapping.value);ElMessage.success('已复制')}catch{ElMessage.error('复制失败，请手动选择复制')}}
async function copy(value){try{await navigator.clipboard.writeText(String(value||''));ElMessage.success('已复制')}catch{ElMessage.error('复制失败，请手动选择复制')}}
async function meterAction(m,kind){actionMeter.value=m;actionKind.value=kind;if(['recharge','balance'].includes(kind)){amount.value=kind==='recharge'?10:m.balance_kwh;actionOpen.value=true;return}try{if(kind==='reset'){await ElMessageBox.prompt('仅清零此模拟设备的累计读数，不删除天枢历史。','累计读数清零',{inputPlaceholder:'输入：清零模拟电表',inputValidator:v=>v==='清零模拟电表'||'请准确输入确认文字'});await api('meter-action',{id:m.id,action:'reset',confirmation:'清零模拟电表'})}else{await ElMessageBox.confirm('仅改变模拟设备状态，不连接物理硬件。',m.relay_on?'模拟现场断开':'模拟现场接通',{type:'warning'});await api('meter-action',{id:m.id,action:'relay',relay_on:!m.relay_on})}await load()}catch(e){if(e?.message)ElMessage.error(e.message)}}
async function saveAction(){saving.value=true;try{await api('meter-action',{id:actionMeter.value.id,action:actionKind.value,amount:amount.value});actionOpen.value=false;await load();ElMessage.success('模拟读数已更新')}catch(e){ElMessage.error(e.message)}finally{saving.value=false}}
onMounted(async()=>{try{csrf=(await api('session')).csrf;await load();timer=setInterval(load,1000)}catch(e){error.value=e.message}});onBeforeUnmount(()=>clearInterval(timer));
</script>
